FROM books b JOIN (VALUES
  ('the-teaching-of-the-twelve-apostles-didache', 'https://www.gutenberg.org/ebooks/42053'),
  ('the-apostolic-tradition-of-hippolytus', 'https://www.gutenberg.org/ebooks/61614'),
  ('leaves-from-st-john-chrysostom', 'https://www.gutenberg.org/ebooks/62447'),
  ('st-bernard-of-clairvauxs-life-of-st-malachy-of-armagh', 'https://www.gutenberg.org/ebooks/25761'),
  ('summa-theologica-part-i-prima-pars', 'https://www.gutenberg.org/ebooks/17611'),
  ('summa-theologica-part-i-ii-pars-prima-secundae', 'https://www.gutenberg.org/ebooks/17897'),
  ('summa-theologica-part-ii-ii-secunda-secundae', 'https://www.gutenberg.org/ebooks/18755'),
  ('summa-theologica-part-iii-tertia-pars', 'https://www.gutenberg.org/ebooks/19950'),
  ('on-prayer-and-the-contemplative-life', 'https://www.gutenberg.org/ebooks/22295'),
  ('commentary-on-the-epistle-to-the-galatians', 'https://www.gutenberg.org/ebooks/1549'),
  ('the-apology-of-the-augsburg-confession', 'https://www.gutenberg.org/ebooks/6744'),
